#!/usr/bin/env python3
"""Freeze Step 9.32 design/preregistration artifacts; no Agent/model is invoked."""
from __future__ import annotations

import hashlib
import json
import tarfile
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "evaluation/v1_2_3"
FINAL = OUT / "step9_26_final_candidate_freeze.json"
FINAL_MANIFEST = OUT / "step9_19_final_candidate_manifest.json"
SNAPSHOT = OUT / "step9_32_baseline_agent_snapshot.tar.gz"

def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def file_hash(path: Path) -> str:
    return digest(path.read_bytes())

def relhashes(relpaths: list[str]) -> list[list[str]]:
    return [[p, file_hash(ROOT / p)] for p in sorted(relpaths)]

def aggregate(rows: list[list[str]]) -> str:
    return digest("".join(f"{p}\t{h}\n" for p, h in sorted(rows)).encode())

def corpus_hash() -> str:
    p = ROOT / "rag_lib/pdfs"
    payload = "".join(f"{file_hash(x)}  {x.relative_to(ROOT).as_posix()}\n"
                      for x in sorted(p.glob("*")) if x.is_file() and not x.name.startswith("._"))
    return digest(payload.encode())

def json_write(path: Path, value: object) -> None:
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")

def main() -> None:
    freeze = json.loads(FINAL.read_text(encoding="utf-8"))
    final_manifest = json.loads(FINAL_MANIFEST.read_text(encoding="utf-8"))
    agent_rows = freeze["agent_behavior_files"]
    mismatches = []
    for rel, expected in agent_rows:
        if rel == "runtime:deepseek_nonsecret_configuration":
            actual = expected  # identity is the recorded non-secret runtime fingerprint; no .env read.
        elif rel == "rag_lib/pdfs/":
            actual = corpus_hash()
        else:
            p = ROOT / rel
            actual = file_hash(p) if p.is_file() else None
        if actual != expected:
            mismatches.append({"path": rel, "expected_sha256": expected, "actual_sha256": actual})
    current_agent_sha = aggregate(agent_rows)
    if mismatches or current_agent_sha != freeze["agent_aggregate_sha256"]:
        raise SystemExit(f"FAIL_CLOSED: baseline candidate mismatch: {mismatches}")
    if not SNAPSHOT.is_file():
        raise SystemExit("FAIL_CLOSED: baseline reconstruction snapshot absent")

    with tarfile.open(SNAPSHOT, "r:gz") as tar:
        snapshot_members = []
        snapshot_hashes = {}
        for member in sorted((m for m in tar.getmembers() if m.isfile()), key=lambda m: m.name):
            raw = tar.extractfile(member).read()
            member_hash = digest(raw)
            snapshot_hashes[member.name] = member_hash
            snapshot_members.append({"path": member.name, "sha256": member_hash, "bytes": member.size})
    for rel, expected in agent_rows:
        if rel == "runtime:deepseek_nonsecret_configuration":
            continue
        if rel == "rag_lib/pdfs/":
            rows = [[p, h] for p, h in snapshot_hashes.items() if p.startswith("rag_lib/pdfs/")]
            archived_corpus = digest("".join(f"{h}  {p}\n" for p, h in sorted(rows)).encode())
            if archived_corpus != expected:
                raise SystemExit("FAIL_CLOSED: baseline snapshot corpus does not match candidate freeze")
        elif snapshot_hashes.get(rel) != expected:
            raise SystemExit(f"FAIL_CLOSED: baseline snapshot member does not match candidate freeze: {rel}")
    snapshot_sha = file_hash(SNAPSHOT)

    config_paths = [".python-version", "requirements-lock.txt", ".env.example", "configs/requirements.yaml", "configs/stages.yaml"]
    config_paths += sorted(p.relative_to(ROOT).as_posix() for p in (ROOT / "configs/prompts").glob("*.txt") if not p.name.startswith("._"))
    config_rows = relhashes(config_paths)
    rag_rows = relhashes(["rag_client.py", "local_embeddings.py", "rag_lib/.rag_db/bge-small-zh-v1.5-ch400-v1/index.faiss", "rag_lib/.rag_db/bge-small-zh-v1.5-ch400-v1/index.pkl"])
    rag_rows.append(["rag_lib/pdfs/", corpus_hash()])
    rag_rows.sort()

